<script setup lang="ts">
import {useWorkbench} from '../stores/workbench';import {fmt} from '../api/client';const s=useWorkbench();
</script><template><div v-if="s.summary"><div class="stat-grid compact"><div class="stat-card" v-for="(label,key) in {bus:'母线',gen:'机组',branch:'支路'}" :key="key"><span>{{label}}</span><strong>{{fmt(s.summary.counts?.[key],0)}}<small>个</small></strong></div><div class="stat-card"><span>网状支路</span><strong>{{fmt(s.summary.topology?.meshed,0)}}<small>条</small></strong></div></div><div class="panel-pad soft-panel"><div class="detail-grid"><div><span>断面时刻</span><strong>{{s.summary.time||'—'}}</strong></div><div><span>标幺基准</span><strong>{{s.summary.baseMVA||100}} MVA</strong></div><div><span>总有功负荷</span><strong>{{fmt(s.summary.totals?.pd_mw)}} MW</strong></div><div><span>总有功出力</span><strong>{{fmt(s.summary.totals?.pg_mw)}} MW</strong></div><div><span>平衡母线</span><strong>B175</strong></div><div><span>孤岛型支路</span><strong>{{fmt(s.summary.topology?.bridges,0)}} 条</strong></div></div></div><div class="two-columns"><section><h3>母线类型</h3><div class="data-list"><div v-for="(count,name) in s.summary.bus_types" :key="name"><span>{{name}}</span><strong>{{count}}</strong></div></div></section><section><h3>电压等级</h3><div class="data-list"><div v-for="v in s.summary.voltage_levels" :key="v.kv"><span>{{v.kv}} kV</span><strong>{{v.count}} 母线</strong></div></div></section></div><h3>数据质量记录</h3><p class="muted">当前断面异常统计</p><div class="quality-list"><div v-for="q in s.summary.quality" :key="q.code" class="quality-row"><span class="finding-code" :class="q.severity">{{q.code}}</span><div><strong>{{q.message}}</strong><details v-if="q.targets?.length"><summary>查看关联对象（{{q.targets.length}}）</summary><code>{{q.targets.join('、')}}</code></details></div><span v-if="q.count!==undefined" class="count-pill">{{q.count}}</span></div></div><p class="footnote">功率 MW / Mvar / MVA · 电压 p.u. · 相角 rad</p></div><el-skeleton v-else :rows="8" animated/></template>